/**********************************************************************/*/* AppleShare.r/*/* This is the RezIIGS source for the AppleShare Control Panel/* (the assembly language version)./*/* 26-Aug-91 MSD	Version 2.0d2.  Changed the "Connect as..."/*			string so there is a newline before the server/*			name (like the old CDEV).  Key equivalents for/*			Cancel/Quit buttons are now Esc (the event hooks/*			translate Command-period to Esc)./*/* 26-Aug-91 MSD	Version 2.0d3.  Turn off fCtlCanBeTarget bit for/*			the volume list since there are no other/*			targettable controls, so why draw a focus frame?/*			Turn off wantMachine so I can display my own/*			error message.  Turn on wantRect and wantCreate./* 27-Aug-91 MSD	Turned off wantRect and wantCreate.  Turned on/*			wantMachine.  Removed extra control lists./*/* 06-Sep-91 MSD	Version 2.0d4.  Added a new alert for servers/*			or volumes whose passwords haven't been stored/*			in the message center (i.e. not mounted by/*			the AppleShare Control Panel)./* 15-Sep-91 MSD	In the volume list dialog, changed the "Quit"/*			button to "Cancel"./* 20-Sep-91 MSD	Version 2.0d5.  Changed to the yellow-folder/*			icon used by Finder and EasyMount./* 27-Sep-91 MSD	Added an error message for when NBP is busy./* 10-Oct-91 MSD	Version 2.0d6.  Fixed the "webbed hand" appear-/*			ance of the icon where there is a white space/*			between the thumb and fingers (noticeable when/*			booting and icon is displayed on desktop)./*  3-Nov-91 DAL	Fixed spelling of "unkown" in unknown-error msg./*  7-Nov-91 MSD	Version 2.0d10.  Made the main window wider since/*			it now has its own window (as of System 6).  Fixed/*			coordinates for OK button to be width-independent./*  2-Dec-91 MSD	Version 2.0d11.  Changed the user name line edit/*			to 31 characters./*  7-Feb-92 MSD	Changed version to 2.0 final for 6.0d70 (GM)./*/**********************************************************************//*/*  Begin 6.0.1/*/*  2-Apr-92 DAL	2.1d1 for 6.0.1. Forces arrow cursor when closing/*			Connect As window./*/*  4-Mar-93 DAL	2.1d14 for 6.0.1d14.  Added AFP2.1 stuff./*/* 25-Mar-93 DAL	2.1d15 for 6.0.1d15.  Removed AFP2.1, fix checkboxes./*/* 1-Apr-93 SS		2.1 (release) for 6.0.1d16./*/**********************************************************************/#include "TypesIIGS.r"#define wantEdit	$0800/**********************************************************************	Definitions for flags used in keyboard equivalents/**********************************************************************/#define keyPad		$2000#define controlKey	$1000#define optionKey	$0800#define capsLock	$0400#define shiftKey	$0200#define appleKey	$0100#define	escChar		"\$1B"/**********************************************************************		The CDEV code and flags/**********************************************************************/read rCDEVCode (1,Convert) "AppleShare.code";resource rCDEVFlags (1) {	wantBoot+wantMachine+wantInit+wantClose+wantEvents		+wantHit+wantRun+wantEdit,	1,					/* enabled */	2,					/* version 2 */	1,					/* ROM 1 or later */	0,					/* reserved */	{0,0,172,280},				/* display rectangle */	"AppleShare",				/* CDEV name (title) */	"Mark Day",				/* Author's name */	"v2.1";				/* version number */};/**********************************************************************		Control List for about box/**********************************************************************/#define aboutText	1resource rControlList (2) {	{aboutText};};resource rControlTemplate (aboutText) {	aboutText,	{38,5,138,280},				/* from DirectConnect */	statTextControl { {		ctlVisible,		fCtlProcNotPtr+refIsResource,		0,				/* refcon */		aboutText			/* ID of text */	} };};resource rTextForLETextBox2 (aboutText) {	"The AppleShare Control Panel allows you to connect "	"to an AppleShare File Server that supports AFP 2.0, "	"and mount volumes from that server.  In addition, volumes "	"can be mounted automatically at system startup.";};/**********************************************************************		The controls from the main CDEV window/**********************************************************************/#define ServerString	11#define ServerList	12#define ServerOKButton	13#define ZoneString	14#define ZoneList	15#define UserString	16#define UserLE		17#define LeftEdge	10#define RightEdge	270#define CenterHoriz	((LeftEdge+RightEdge)/2)#define fInsideScroll	4#define fSingleSelect	2#define fCStrings	1resource rControlList (1) { {	UserString,UserLE,	ZoneString,ZoneList,	ServerString,ServerList,ServerOKButton} };resource rControlTemplate (ServerString) {	ServerString,	{6,LeftEdge,16,RightEdge},	statTextControl { {		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		ServerString		/* text ID */	} };};resource rTextForLETextBox2 (ServerString) {	"Select a file server:";};resource rControlTemplate (ServerList) {	ServerList,	{17,LeftEdge,59,RightEdge},	listControl { {		ctlVisible,		fCtlCanBeTarget+fCtlWantsEvents+fCtlIsMultiPart+			fCtlProcNotPtr+refIsResource,		0,		/* refcon */		0,		/* listSize = empty */		4,		/* listView */		fInsideScroll,	/* listType = scroll bar inside */		1,		/* listStart */		10,		/* listMemHeight (normal for text) */		5,		/* listMemSize (default) */		0		/* listRef (no list yet) */	} };};resource rControlTemplate (ServerOKButton) {	ServerOKButton,	{65,CenterHoriz-45,78,CenterHoriz+45},	simpleButtonControl { {		DefaultButton+ctlInactive,		fCtlWantsEvents+fCtlProcNotPtr+refIsResource,		0,			/* refcon */		ServerOKButton,		/* titleRef */		0,			/* color table ref */		{"\n","\n",0,0}		/* Return/Enter are equivalents */	} };};resource rPString (ServerOKButton) {	"OK"};resource rControlTemplate (ZoneString) {	ZoneString,	{87,LeftEdge,97,RightEdge},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		ZoneString		/* text ID */	}}};resource rTextForLETextBox2 (ZoneString) {	"AppleTalk Zones:";};resource rControlTemplate (ZoneList) {	ZoneList,	{98,LeftEdge,140,RightEdge},	listControl { {		ctlVisible,		fCtlCanBeTarget+fCtlWantsEvents+fCtlIsMultiPart+			fCtlProcNotPtr+refIsPtr,		0,		/* refcon */		0,		/* listSize = empty */		4,		/* listView */		fInsideScroll+fSingleSelect,		1,		/* listStart */		10,		/* listMemHeight (normal for text) */		5,		/* listMemSize (default) */		0		/* listRef (empty list) */	} };};resource rListRef (ZoneList) { {} };resource rControlTemplate (UserString) {	UserString,	{146,LeftEdge,156,RightEdge},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		UserString		/* text ID */	}}};resource rTextForLETextBox2 (UserString) {	"User Name:";};resource rControlTemplate (UserLE) {	UserLE,	{156,LeftEdge,170,RightEdge},	editLineControl { {		ctlVisible,		fCtlCanBeTarget+fCtlWantsEvents+fCtlProcNotPtr,		0,		/* refcon */		31,		/* max length */		0		/* ref to default value */	} };};/**********************************************************************		Resources for the "Connect as..." dialog/**********************************************************************/#define rConnDlg	20#define rGuest		21#define rRegistered	22#define rCCancel	23#define rCOK		24#define rCSetPass	25#define rConnString	26#define rNameStr	27#define rNameLE		28#define rPassStr	29#define rPassLE		30#define rScrambled	31		/* says "(Scrambled)" */#define rClearText	32		/* says "(Clear text)" */#define rAlreadyConn	33		/* "Already connected..." */#define rNameStatText	34		/* user name as static text */#define	fLEPassword	$8000		/* add to max size for password field */resource rWindParam1 (rConnDlg) {	fAlert+fCtlTie,			/* note: invisible! */	rConnDlg,			/* no title */	0,				/* refcon */	{0,0,0,0},			/* zoom rect */	0,				/* no color table */	{0,0},				/* window origin */	{0,0},				/* data size */	{0,0},				/* maximum size */	{0,0},				/* scroll size for arrows */	{0,0},				/* scroll size for page up/down */	0,				/* wInfoRefCon */	0,				/* wInfoHeight */	{18,6,195,312},			/* window's rect for 320 mode */	inFront,	rConnDlg,			/* reference to control list */	ResourceToResource+RefIsResource*$100};resource rPString (rConnDlg) {	"Connect As"};resource rControlList (rConnDlg) {{	rConnString, rGuest, rRegistered, rNameStr, rNameLE, rPassStr,	rPassLE, rScrambled, rClearText, rCCancel, rCOK, rCSetPass,	rAlreadyConn,rNameStatText}};resource rControlTemplate (rConnString) {	rConnString,	{15,15,36,305},	statTextControl {{		CtlInactive+ctlInvis+fSubstituteText+fSubTextIsPascal,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rConnString	}}};resource rTextForLETextBox2 (rConnString) {	"Connect to the file server\nÒ*0Ó as:"};resource rControlTemplate (rAlreadyConn) {	rAlreadyConn,	{15,15,36,305},	statTextControl {{		CtlInactive+ctlInvis+fSubstituteText+fSubTextIsPascal,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rAlreadyConn	}}};resource rTextForLETextBox2 (rAlreadyConn) {	"Already connected to the file server Ò*0Ó as:"};resource rControlTemplate (rGuest) {	rGuest,	{53,45,63,200},	radioControl {{		ctlVisible+1,		/* 1 = family number */		fCtlWantsEvents+fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rGuest,			/* title reference */		0,			/* initial value */		0,			/* color table reference */		{			"g","G",	/* Command-G is equivalent */			appleKey,			controlKey+optionKey+appleKey		}	}}};resource rPString (rGuest) {	"Guest"};resource rControlTemplate (rRegistered) {	rRegistered,	{68,45,78,200},	radioControl {{		ctlVisible+1,		/* 1 = family number */		fCtlWantsEvents+fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rRegistered,		/* title reference */		1,			/* initial value */		0,			/* color table reference */		{			"r","R",	/* Command-R is equivalent */			appleKey,			controlKey+optionKey+appleKey		}	}}};resource rPString (rRegistered) {	"Registered User"};resource rControlTemplate (rNameStr) {	rNameStr,	{92,15,102,65},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rNameStr	}}};resource rTextForLETextBox2 (rNameStr) {	"Name:"};resource rControlTemplate (rNameLE) {	rNameLE,	{90,70,104,300},	editLineControl { {		ctlVisible,		fCtlCanBeTarget+fCtlWantsEvents+			fCtlProcNotPtr,		0,		/* refcon */		32,		/* max length */		0		/* ref to default value */	} };};resource rControlTemplate (rNameStatText) {	rNameStatText,	{92,70,102,300},	statTextControl {{		CtlInactive+ctlInvis+fSubstituteText+fSubTextIsPascal,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rNameStatText	}}};resource rTextForLETextBox2 (rNameStatText) {	"*1"};resource rControlTemplate (rPassStr) {	rPassStr,	{110,15,120,85},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rPassStr	}}};resource rTextForLETextBox2 (rPassStr) {	"Password:"};resource rControlTemplate (rPassLE) {	rPassLE,	{108,103,122,180},	editLineControl { {		ctlVisible,		fCtlCanBeTarget+fCtlWantsEvents+			fCtlProcNotPtr,		0,		/* refcon */		8+fLEPassword,	/* max length */		0		/* ref to default value */	} };};resource rControlTemplate (rScrambled) {	rScrambled,	{110,205,120,295},	statTextControl {{		ctlInactive+ctlInvis+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rScrambled	}}};resource rTextForLETextBox2 (rScrambled) {	"(Scrambled)"};resource rControlTemplate (rClearText) {	rClearText,	{110,205,120,295},	statTextControl {{		ctlInactive+ctlInvis+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rClearText	}}};resource rTextForLETextBox2 (rClearText) {	"(Clear text)"};resource rControlTemplate (rCCancel) {	rCCancel,	{137,40,150,140},	simpleButtonControl { {		ctlVisible,		fCtlWantsEvents+fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rCCancel,		/* titleRef */		0,			/* color table ref */		{			escChar,escChar, /* Esc is equivalent */			0,			controlKey+optionKey+appleKey		}	} };};resource rPString (rCCancel) {	"Cancel"};resource rControlTemplate (rCOK) {	rCOK,	{137,160,150,260},	simpleButtonControl { {		DefaultButton+ctlVisible,		fCtlWantsEvents+fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rCOK,			/* titleRef */		0,			/* color table ref */		{"\n","\n",0,0}		/* Return/Enter are equivalents */	} };};resource rPString (rCOK) {	"OK"};resource rControlTemplate (rCSetPass) {	rCSetPass,	{155,40,168,155},	simpleButtonControl { {		ctlVisible,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rCSetPass		/* titleRef */	} };};resource rPString (rCSetPass) {	"Set Password"};/**********************************************************************		Resources for the volume list dialog/**********************************************************************/#define rVolDlg		40#define rSelStr		41		/* "Select volumes to mount..." */#define rVolList	42#define	rCheckedStr	43		/* "Checked volumes will..." */#define rNameOnly	44		/* Save My Name Only button */#define rNameAndPass	45		/* Save My Name And Password */#define rVQuit		46		/* Quit button */#define rVOK		47		/* OK button */#define rVolIcon	48		/* AppleShare icon */#define	rVSrvrName	49		/* Server name */#define rSampleCheck	50		/* example checked box */#define idVolList	1#define idNameOnly	2#define idNameAndPass	3#define	idVQuit		4#define	idVOK		5#define testMemNever	$0040resource rWindParam1 (rVolDlg) {	fAlert+fCtlTie,			/* note: invisible! */	rVolDlg,			/* no title */	0,				/* refcon */	{0,0,0,0},			/* zoom rect */	0,				/* no color table */	{0,0},				/* window origin */	{0,0},				/* data size */	{0,0},				/* maximum size */	{0,0},				/* scroll size for arrows */	{0,0},				/* scroll size for page up/down */	0,				/* wInfoRefCon */	0,				/* wInfoHeight */	{18,6,195,312},			/* window's rect for 320 mode */	inFront,	rVolDlg,			/* reference to control list */	ResourceToResource+RefIsResource*$100};resource rPString (rVolDlg) {	"Select Volumes"};resource rControlList (rVolDlg) {{	rSampleCheck,	rSelStr,rVolList,rCheckedStr,rNameOnly,rNameAndPass,	rVQuit,rVOK,rVolIcon,rVSrvrName}};resource rControlTemplate (rSelStr) {	rSelStr,	{41,22,51,285},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rSelStr	}}};resource rTextForLETextBox2 (rSelStr) {	"Select the items you want:"};resource rControlTemplate (rVolList) {	idVolList,	{53,22,99,285},	listControl {{		ctlVisible+testMemNever,		fCtlWantsEvents+fCtlIsMultiPart+fCtlProcNotPtr+refIsResource,		0,		/* refcon */		0,		/* listSize (for now) */		4,		/* listView */		fInsideScroll,	/* listType = scroll bar inside */		1,		/* listStart */		11,		/* listMemHeight (10 is default) */		6,		/* listMemSize (extra byte for checked flag) */		0		/* listRef (no list yet) */	}}};resource rControlTemplate (rCheckedStr) {	rCheckedStr,	{102,37,122,302},	statTextControl {{		CtlInactive,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rCheckedStr	}}};resource rTextForLETextBox2 (rCheckedStr) {	"Checked volumes (         ) will be\n"	"opened at system startup time."};/*	Note: The check box is inactive.  It also has a non-zero	height (its normal height of 10 pixels), but a zero width.	This combination causes the checkbox to still be drawn,	but not to be dimmed, and not to track.  This is probably	a bug (it shouldn't draw since the rectangle is empty),	but it is doing exactly what I need!*/resource rControlTemplate (rSampleCheck) {	rSampleCheck,	{102,173,112,173},	checkControl {{		ctlInactive,		fCtlProcNotPtr+refIsResource,		0,		rSampleCheck,		/* no title 