ialog/**********************************************************************/#define rVPDialog	60#define rVPText1	61		/* volume name */#define rVPText2	62		/* "Enter a password..." */#define	rVPLE		63		/* line edit box */#define rVPCancel	64		/* Cancel button */#define rVPOK		65		/* OK button */#define rVPIcon		66#define rVPText3	67		/* "Password:"#define idVPOK		1#define idVPCancel	2#define idVPText1	3#define	idVPText2	4#define	idVPLE		5#define idVPIcon	6#define idVPText3	7resource rWindParam1 (rVPDialog) {	fAlert+fCtlTie,			/* note: invisible! */	rVPDialog,			/* no title */	0,				/* refcon */	{0,0,0,0},			/* zoom rect */	0,				/* no color table */	{0,0},				/* window origin */	{0,0},				/* data size */	{0,0},				/* maximum size */	{0,0},				/* scroll size for arrows */	{0,0},				/* scroll size for page up/down */	0,				/* wInfoRefCon */	0,				/* wInfoHeight */	{40,8,150,312},			/* window's rect for 320 mode */	inFront,	rVPDialog,			/* reference to control list */	ResourceToResource+RefIsResource*$100};resource rPString (rVPDialog) {	"Volume Password"};resource rControlList (rVPDialog) {{	rVPIcon,rVPText1,rVPText2,rVPText3,rVPLE,rVPCancel,rVPOK}};resource rControlTemplate (rVPText1) {	idVPText1,	{14,85,34,300},	statTextControl {{		ctlInactive+fSubstituteText+fSubTextIsPascal,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rVPText1	}}};resource rTextForLETextBox2 (rVPText1) {	"Ò*2Ó"};resource rControlTemplate (rVPText2) {	idVPText2,	{50,20,60,290},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rVPText2	}}};resource rTextForLETextBox2 (rVPText2) {	"Enter the password for this volume:"};resource rControlTemplate (rVPText3) {	idVPText3,	{63,20,75,100},	statTextControl {{		CtlInactive+fBlastText,		fCtlProcNotPtr+refIsResource,		0,			/* refcon */		rVPText3	}}};resource rTextForLETextBox2 (rVPText3) {	"Password:"};resource rContr